import{_ as e,o as s,c as n,a0 as t}from"./chunks/framework.CShDTZbC.js";const h=JSON.parse('{"title":"Await Grammar","description":"","frontmatter":{},"headers":[],"relativePath":"grammar/await.md","filePath":"grammar/await.md"}'),i={name:"grammar/await.md"};function d(o,a,l,r,p,c){return s(),n("div",null,[...a[0]||(a[0]=[t(`<h1 id="await-grammar" tabindex="-1">Await Grammar <a class="header-anchor" href="#await-grammar" aria-label="Permalink to &quot;Await Grammar&quot;">​</a></h1><p><code>await</code> adalah prefix expression yang mengambil handle hasil <code>async</code> dan memastikan operasinya sudah selesai sebelum nilainya dipakai.</p><h2 id="syntax" tabindex="-1">Syntax <a class="header-anchor" href="#syntax" aria-label="Permalink to &quot;Syntax&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>await &lt;expression&gt;</span></span></code></pre></div><p><code>await</code> mengikat lebih erat dari operator binary/perbandingan, tapi lebih longgar dari member access (<code>.</code>):</p><ul><li><code>await value != null</code> berarti <code>(await value) != null</code></li><li><code>await users.data</code> berarti <code>(await users).data</code></li></ul><h2 id="source" tabindex="-1">Source <a class="header-anchor" href="#source" aria-label="Permalink to &quot;Source&quot;">​</a></h2><div class="language-rupa vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">rupa</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>users = async db.getUser()</span></span>
<span class="line"><span>handle = await users</span></span></code></pre></div><p>AST:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Assignment:</span></span>
<span class="line"><span>  Target:</span></span>
<span class="line"><span>    Identifier: handle</span></span>
<span class="line"><span>  Value:</span></span>
<span class="line"><span>    Await:</span></span>
<span class="line"><span>      Identifier: users</span></span></code></pre></div><h2 id="await-structure" tabindex="-1">Await structure <a class="header-anchor" href="#await-structure" aria-label="Permalink to &quot;Await structure&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Await</span></span>
<span class="line"><span>└── Expression  (ekspresi yang menghasilkan async handle)</span></span></code></pre></div><h2 id="how-it-works" tabindex="-1">How it works <a class="header-anchor" href="#how-it-works" aria-label="Permalink to &quot;How it works&quot;">​</a></h2><p><code>await &lt;expr&gt;</code> mengevaluasi <code>&lt;expr&gt;</code>, lalu mengembalikan handle <code>{status, data, error}</code> yang sudah final (<code>SUCCESS</code> atau <code>ERROR</code> — lihat <a href="./async.html">async.md</a>). Karena <code>async</code> saat ini dievaluasi eager, handle-nya sudah selesai pada saat <code>await</code> dipanggil.</p><p><code>await</code> sendiri mengembalikan handle-nya, <strong>bukan</strong> langsung <code>data</code>-nya — pakai <code>.data</code> untuk mengambil hasilnya:</p><div class="language-rupa vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">rupa</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>users = async dbtest.getUser()</span></span>
<span class="line"><span>d = (await users).data</span></span></code></pre></div><p><code>(await users)</code> → <code>{status: SUCCESS, data: [...], error: undefined}</code><code>.data</code> → <code>[...]</code></p>`,17)])])}const g=e(i,[["render",d]]);export{h as __pageData,g as default};
